func glPush(c *port.Cells, stride int32) int32 {
	// Append a row of zeros and answer its index.
	var row int32 = port.CellsLen(c) / stride
	var i int32 = 0
	for i < stride {
		port.CellsPush(c, 0)
		i += 1
	}
	return row
}

