func glAddIf(v int32, by int32) int32 {
	// v + by for a present value (v >= 0); an absent one stays -1.
	if v < 0 {
		return v
	}
	return v + by
}

func GlAppend(dgrl *port.Cells, dgfl *port.Cells, dggp *port.Cells, dgrg *port.Cells, pgrl *port.Cells, pgfl *port.Cells, pggp *port.Cells, pgrg *port.Cells, orf int32) int32 {
	// Concatenate a page's graphics arenas onto the document's. Re-based: every `group` (by the document's `ggp` rows so far)
	// and every member run of a group (by `orf`, the rows of `refs` the document had before the page's were appended). Not
	// re-based: a region's subject (an evidence row) and a member reference's own index (evidence rows). Answers 0.
	var og int32 = port.CellsLen(dggp) / 12
	var i int32 = 0
	var n int32 = 0
	var k int32 = 0
	var v int32 = 0
	n = port.CellsLen(pgrl) / 24
	for i < n {
		k = 0
		for k < 24 {
			v = port.CellsAt(pgrl, (i*24)+k)
			if k == 19 {
				v = glAddIf(v, og)
			}
			port.CellsPush(dgrl, v)
			k += 1
		}
		i += 1
	}
	i = 0
	n = port.CellsLen(pgfl) / 16
	for i < n {
		k = 0
		for k < 16 {
			v = port.CellsAt(pgfl, (i*16)+k)
			if k == 12 {
				v = glAddIf(v, og)
			}
			port.CellsPush(dgfl, v)
			k += 1
		}
		i += 1
	}
	i = 0
	n = port.CellsLen(pggp) / 12
	for i < n {
		k = 0
		for k < 12 {
			v = port.CellsAt(pggp, (i*12)+k)
			if (k == 2) || ((k == 4) || (k == 6)) {
				v = glAddIf(v, orf)
			}
			port.CellsPush(dggp, v)
			k += 1
		}
		i += 1
	}
	i = 0
	n = port.CellsLen(pgrg)
	for i < n {
		port.CellsPush(dgrg, port.CellsAt(pgrg, i))
		i += 1
	}
	return 0
}

func glRunOk(first int32, cnt int32, limit int32) int32 {
	// 1 when (first, count) is absent (first -1, count 0) or lies inside [0, limit).
	if first < 0 {
		if cnt == 0 {
			return 1
		}
		return 0
	}
	if cnt < 0 {
		return 0
	}
	if (first + cnt) > limit {
		return 0
	}
	return 1
}

func GlCheck(grl *port.Cells, gfl *port.Cells, ggp *port.Cells, grg *port.Cells, refs *port.Cells) int32 {
	// 0 for sound graphics arenas, else the first broken thing: 1 a stride; 2 a `grl` or `gfl` group outside `ggp` (or below -1);
	// 3 a `ggp` member run outside `refs` or a `ggp` of an unknown kind; 4 a `grl` orientation outside `go`, a negative
	// thickness, or a box that is upside down (in `grl`, `gfl` or `grg`); 5 a `grg` of an unknown kind or a half subject (an
	// arena and no row, or a row and no arena); 6 a `refs` reference into one of these arenas (`ea` 41, 43, 44, 45) that has no
	// such row.
	var nr int32 = port.CellsLen(grl) / 24
	var nf int32 = port.CellsLen(gfl) / 16
	var ng int32 = port.CellsLen(ggp) / 12
	var nc int32 = port.CellsLen(grg) / 16
	var nrf int32 = port.CellsLen(refs) / 2
	var i int32 = 0
	var v int32 = 0
	var w int32 = 0
	if (port.CellsLen(grl) % 24) != 0 {
		return 1
	}
	if (port.CellsLen(gfl) % 16) != 0 {
		return 1
	}
	if (port.CellsLen(ggp) % 12) != 0 {
		return 1
	}
	if (port.CellsLen(grg) % 16) != 0 {
		return 1
	}
	if (port.CellsLen(refs) % 2) != 0 {
		return 1
	}
	for i < nr {
		v = port.CellsAt(grl, (i*24)+19)
		if (v < -1) || (v >= ng) {
			return 2
		}
		v = port.CellsAt(grl, (i*24)+10)
		if (v < 1) || (v > 3) {
			return 4
		}
		if port.CellsAt(grl, (i*24)+9) < 0 {
			return 4
		}
		if (port.CellsAt(grl, (i*24)+1) > port.CellsAt(grl, (i*24)+3)) || (port.CellsAt(grl, (i*24)+2) > port.CellsAt(grl, (i*24)+4)) {
			return 4
		}
		i += 1
	}
	i = 0
	for i < nf {
		v = port.CellsAt(gfl, (i*16)+12)
		if (v < -1) || (v >= ng) {
			return 2
		}
		if (port.CellsAt(gfl, (i*16)+1) > port.CellsAt(gfl, (i*16)+3)) || (port.CellsAt(gfl, (i*16)+2) > port.CellsAt(gfl, (i*16)+4)) {
			return 4
		}
		i += 1
	}
	i = 0
	for i < ng {
		if glRunOk(port.CellsAt(ggp, (i*12)+2), port.CellsAt(ggp, (i*12)+3), nrf) == 0 {
			return 3
		}
		if glRunOk(port.CellsAt(ggp, (i*12)+4), port.CellsAt(ggp, (i*12)+5), nrf) == 0 {
			return 3
		}
		if glRunOk(port.CellsAt(ggp, (i*12)+6), port.CellsAt(ggp, (i*12)+7), nrf) == 0 {
			return 3
		}
		v = port.CellsAt(ggp, (i*12)+1)
		if (v < 1) || (v > 3) {
			return 3
		}
		i += 1
	}
	i = 0
	for i < nc {
		v = port.CellsAt(grg, (i*16)+5)
		if (v < 1) || (v > 3) {
			return 5
		}
		v = port.CellsAt(grg, (i*16)+7)
		w = port.CellsAt(grg, (i*16)+8)
		if (v < 0) && (w >= 0) {
			return 5
		}
		if (v >= 0) && (w < 0) {
			return 5
		}
		if (port.CellsAt(grg, (i*16)+1) > port.CellsAt(grg, (i*16)+3)) || (port.CellsAt(grg, (i*16)+2) > port.CellsAt(grg, (i*16)+4)) {
			return 4
		}
		i += 1
	}
	i = 0
	for i < nrf {
		v = port.CellsAt(refs, i*2)
		w = port.CellsAt(refs, (i*2)+1)
		if v == 41 {
			if (w < 0) || (w >= nr) {
				return 6
			}
		}
		if v == 43 {
			if (w < 0) || (w >= nf) {
				return 6
			}
		}
		if v == 44 {
			if (w < 0) || (w >= ng) {
				return 6
			}
		}
		if v == 45 {
			if (w < 0) || (w >= nc) {
				return 6
			}
		}
		i += 1
	}
	return 0
}

