var GlFx [16]int32 = [16]int32{
	0, 18, 24, 3,
	18, 11, 16, 2,
	29, 6, 12, 3,
	35, 9, 16, 3,
}

func glBegin(t *strings.Builder, pr int32, started int32, code int32) int32 {
	if started == 1 {
		port.TextAscii(t, ",")
	}
	if pr == 1 {
		json.JsIndent(t, 3)
	}
	port.TextAscii(t, "\"")
	GlkEmitName(t, code)
	port.TextAscii(t, "\":")
	if pr == 1 {
		port.TextAscii(t, " ")
	}
	return 1
}

func glBits(t *strings.Builder, pr int32, v int32, which int32) int32 {
	// A bit set as an array of names (which 10 `gq`, 11 `gqf`, 12 `gs`).
	var b int32 = 0
	var k int32 = 0
	var bit int32 = 1
	port.TextAscii(t, "[")
	for b < 16 {
		if (v & bit) != 0 {
			json.JsFsep(t, pr, k)
			port.TextAscii(t, "\"")
			if which == 10 {
				GqEmitName(t, bit)
			}
			if which == 11 {
				GqfEmitName(t, bit)
			}
			if which == 12 {
				GsEmitName(t, bit)
			}
			port.TextAscii(t, "\"")
			k += 1
		}
		bit *= 2
		b += 1
	}
	port.TextAscii(t, "]")
	return 0
}

func glField(t *strings.Builder, pr int32, c *port.Cells, stride int32, row int32, r int32, started int32) int32 {
	// One printed field of a row, by row `r` of `gl-fd`.
	var f int32 = GlFd[r*6+1]
	var kind int32 = GlFd[r*6+2]
	var key int32 = GlFd[r*6+3]
	var dflt int32 = GlFd[r*6+4]
	var arg int32 = GlFd[r*6+5]
	var p int32 = (row * stride) + f
	var s int32 = started
	if ((kind == 1) || ((kind == 2) || (((kind >= 6) && (kind <= 9)) || (kind >= 10)))) && (port.CellsAt(c, p) == dflt) {
		return started
	}
	if kind == 1 {
		s = glBegin(t, pr, s, key)
		port.TextI32(t, port.CellsAt(c, p))
		return s
	}
	if kind == 2 {
		s = glBegin(t, pr, s, key)
		json.JsCpt(t, port.CellsAt(c, p))
		return s
	}
	if kind == 3 {
		s = glBegin(t, pr, s, key)
		port.TextAscii(t, "[")
		json.JsCpt(t, port.CellsAt(c, p))
		json.JsFsep(t, pr, 1)
		json.JsCpt(t, port.CellsAt(c, p+1))
		json.JsFsep(t, pr, 1)
		json.JsCpt(t, port.CellsAt(c, p+2))
		json.JsFsep(t, pr, 1)
		json.JsCpt(t, port.CellsAt(c, p+3))
		port.TextAscii(t, "]")
		return s
	}
	if kind == 4 {
		if (port.CellsAt(c, p) == dflt) && (port.CellsAt(c, p+1) == arg) {
			return started
		}
		s = glBegin(t, pr, s, key)
		port.TextAscii(t, "[")
		port.TextI32(t, port.CellsAt(c, p))
		json.JsFsep(t, pr, 1)
		port.TextI32(t, port.CellsAt(c, p+1))
		port.TextAscii(t, "]")
		return s
	}
	if kind == 5 {
		if port.CellsAt(c, p+1) == dflt {
			return started
		}
		s = glBegin(t, pr, s, key)
		port.TextAscii(t, "[\"")
		evidence.EaEmitName(t, port.CellsAt(c, p))
		port.TextAscii(t, "\",")
		if pr == 1 {
			port.TextAscii(t, " ")
		}
		port.TextI32(t, port.CellsAt(c, p+1))
		port.TextAscii(t, "]")
		return s
	}
	if (kind >= 6) && (kind <= 9) {
		s = glBegin(t, pr, s, key)
		port.TextAscii(t, "\"")
		if kind == 6 {
			GoEmitName(t, port.CellsAt(c, p))
		}
		if kind == 7 {
			evidence.RsEmitName(t, port.CellsAt(c, p))
		}
		if kind == 8 {
			GkEmitName(t, port.CellsAt(c, p))
		}
		if kind == 9 {
			RkEmitName(t, port.CellsAt(c, p))
		}
		port.TextAscii(t, "\"")
		return s
	}
	if kind >= 10 {
		s = glBegin(t, pr, s, key)
		glBits(t, pr, port.CellsAt(c, p), kind)
		return s
	}
	return started
}

func glRow(t *strings.Builder, pr int32, a int32, c *port.Cells, row int32) int32 {
	// One row of arena a (1 `grl` .. 4 `grg`) as an object, its fields in stride order.
	var first int32 = GlFx[(a-1)*4+0]
	var cnt int32 = GlFx[(a-1)*4+1]
	var stride int32 = GlFx[(a-1)*4+2]
	var s int32 = 0
	var k int32 = 0
	port.TextAscii(t, "{")
	for k < cnt {
		s = glField(t, pr, c, stride, row, first+k, s)
		k += 1
	}
	json.JsClose(t, pr, 2, s)
	return 0
}

func GlArena(t *strings.Builder, pr int32, started int32, a int32, c *port.Cells) int32 {
	// `"key":[row, ...]` for arena a (1 `grl`, 2 `gfl`, 3 `ggp`, 4 `grg`), as a member of the dump's object; answers 1.
	var stride int32 = GlFx[(a-1)*4+2]
	var n int32 = port.CellsLen(c) / stride
	var i int32 = 0
	if started == 1 {
		port.TextAscii(t, ",")
	}
	if pr == 1 {
		json.JsIndent(t, 1)
	}
	port.TextAscii(t, "\"")
	GlkEmitName(t, a)
	port.TextAscii(t, "\":")
	if pr == 1 {
		port.TextAscii(t, " ")
	}
	port.TextAscii(t, "[")
	for i < n {
		json.JsAelem(t, pr, 1, i)
		glRow(t, pr, a, c, i)
		i += 1
	}
	json.JsAend(t, pr, 1, n)
	return 1
}

func GlEmit(t *strings.Builder, pretty int32, s0 int32, grl *port.Cells, gfl *port.Cells, ggp *port.Cells, grg *port.Cells) int32 {
	// The four arrays as members of the dump's object, `s0` being 1 when a member came before. Answers 1.
	var s int32 = s0
	s = GlArena(t, pretty, s, 1, grl)
	s = GlArena(t, pretty, s, 2, gfl)
	s = GlArena(t, pretty, s, 3, ggp)
	s = GlArena(t, pretty, s, 4, grg)
	return s
}
